def transform(grid):
    """Connect matching border markers; recolor each 4-connected 2 object touched by either guide."""
    h, w = len(grid), len(grid[0])
    vertical = {c for c in range(w) if grid[0][c] == 1 and grid[h - 1][c] == 1}
    horizontal = {r for r in range(h) if grid[r][0] == 1 and grid[r][w - 1] == 1}
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if any(x in vertical or y in horizontal for y, x in comp):
                for y, x in comp:
                    out[y][x] = 1
    for c in vertical:
        for r in range(h):
            out[r][c] = 1
    for r in horizontal:
        for c in range(w):
            out[r][c] = 1
    return out
